<script setup lang="ts">
import {ref,watch} from 'vue';
import {useProjectStore} from '../stores/project';
import {useTasksStore} from '../stores/tasks';
import type {DraftGenerationResolution,RehearsalRequest} from '@loreviva/sdk-ts';
import FieldErrors from './FieldErrors.vue';
import CandidateDiff from './CandidateDiff.vue';
import RehearsalReport from './RehearsalReport.vue';
const s=useProjectStore();const tasks=useTasksStore();const resolution=ref<DraftGenerationResolution>();const selected=ref<string[]>([]);const candidateId=ref('');const rehearsalId=ref('');const historyId=ref('');const error=ref<unknown>();const message=ref('');const inputs=ref<RehearsalRequest['inputs']>([{actor_slot:'',text:''}]);
watch(()=>[s.selectedId,s.basis?.draft_revision,s.basis?.draft_id],()=>{resolution.value=undefined;selected.value=[]});
// Resolution only inspects the saved draft. Candidate and rehearsal submission return task identities, not successful results; use the task store to resume the original admission and read its actual state.
async function resolve(){try{s.assertImpactReady();if(!s.basis||s.dirty)throw Error('请先保存或取消修改');resolution.value=await s.client.call('resolveDraftGeneration',{path:{draft_id:s.basis.draft_id},body:{product_id:s.productId,expected_draft_revision:s.basis.draft_revision,object_id:s.selectedId,module_id:'AUTHORING'}});selected.value=[...resolution.value.support.supported_fields];error.value=undefined}catch(e){error.value=e}}
async function candidate(){try{s.assertImpactReady();if(!s.basis||resolution.value?.state!=='RESOLVED')throw Error('先检查当前配置');candidateId.value=await tasks.createCandidate({product_id:s.productId,expected_draft_revision:s.basis.draft_revision,object_id:s.selectedId,module_id:'AUTHORING',mode:'MOCK',selected_fields:[...selected.value],approved_cost_units:'0'});message.value='候选任务已受理，尚未代表生成成功。';error.value=undefined}catch(e){error.value=e}}
async function resume(){try{s.assertImpactReady();candidateId.value=await tasks.resumeCandidate();error.value=undefined}catch(e){error.value=e}}
async function rehearse(){try{s.assertImpactReady();if(!s.basis)throw Error('先保存草稿');rehearsalId.value=await tasks.rehearse({product_id:s.productId,expected_draft_revision:s.basis.draft_revision,mode:'MOCK',fixture:'COFFEE',inputs:inputs.value,max_cost_units:'0',assertions:['SIGN_CUSTODY','RIGHTS','DUTIES','ISOLATED']});message.value='试演任务已受理，请读取原任务状态。';error.value=undefined}catch(e){error.value=e}}
async function refresh(id:string){try{await tasks.refresh(id);error.value=undefined}catch(e){error.value=e}}
async function cancel(id:string){try{const receipt=await tasks.cancel(id);message.value=receipt.cancel_state+'：不代表已取消外部请求，也不会回滚已提交结果。'}catch(e){error.value=e}}
</script>
<template><section class="panel"><h2>可选协助与试演</h2><p>普通字段可以直接编辑。当前仅合成 Mock、批准费用为 0，不发送到真实模型。</p><FieldErrors :error="error"/><p v-if="message" role="status">{{message}}</p><div class="toolbar"><button :disabled="s.impactBlocked||s.dirty||!s.basis" @click="resolve">检查选中对象的 AUTHORING 配置</button><span v-if="resolution" class="badge">{{resolution.state}}</span></div><template v-if="resolution"><p>配置检查只读取当前修订，不生成、不采购。可支持字段：</p><label v-for="field in resolution.support.supported_fields" :key="field"><input v-model="selected" type="checkbox" :value="field">{{field}}</label><button :disabled="s.impactBlocked||s.dirty||resolution.state!=='RESOLVED'||!selected.length" @click="candidate">生成选中字段 Mock 候选</button></template><button v-if="tasks.pendingCandidate" @click="resume">恢复原候选受理</button><section v-if="candidateId"><p>原任务 {{candidateId}} · {{tasks.views[candidateId]?.task_state}}</p><button @click="refresh(candidateId)">刷新候选任务</button><button @click="cancel(candidateId)">请求取消候选</button><CandidateDiff v-if="tasks.views[candidateId]?.task_state==='COMMITTED'" :task-id="candidateId"/></section><details><summary>隔离 COFFEE 试演</summary><p>最多 20 条输入；每条不超过 2000 字。试演是新任务，关闭此区域不会取消任务。</p><fieldset v-for="(input,i) in inputs" :key="i"><legend>输入 {{i+1}}</legend><label>演员槽位<input v-model="input.actor_slot" placeholder="使用世界初始演员中已有槽位"></label><label>输入文字<textarea v-model="input.text" maxlength="2000" rows="2"/></label><button :disabled="inputs.length===1" @click="inputs.splice(i,1)">移除此条</button></fieldset><button :disabled="inputs.length>=20" @click="inputs.push({actor_slot:'',text:''})">添加输入</button><button class="primary" :disabled="s.impactBlocked||s.dirty||!s.basis" @click="rehearse">受理 Mock 试演</button><section v-if="rehearsalId"><p>原任务 {{rehearsalId}} · {{tasks.views[rehearsalId]?.task_state}}</p><button @click="refresh(rehearsalId)">刷新试演任务</button><button @click="cancel(rehearsalId)">请求取消试演</button><RehearsalReport v-if="tasks.reports[rehearsalId]" :report="tasks.reports[rehearsalId]" :original="tasks.rehearsalContexts[rehearsalId]"/></section></details><details><summary>读取原 ADMIN 任务 / 历史报告</summary><p>可从运行中心任务目录取得标识。缺原受理上下文的候选只展示状态，不允许采用。</p><label>原任务标识<input v-model="historyId"></label><button @click="refresh(historyId)">读取原任务</button><p v-if="tasks.views[historyId]">{{tasks.views[historyId].task_kind}} · {{tasks.views[historyId].task_state}}</p><RehearsalReport v-if="tasks.reports[historyId]" :report="tasks.reports[historyId]" :original="tasks.rehearsalContexts[historyId]"/></details></section></template>
